function.arguments:
{"script": "#!/bin/bash
mkdir -p task_directory; 
for i in {1..5}; do 
  touch task_directory/file$i; 
  perm=$((RANDOM%8))$((RANDOM%8))$((RANDOM%8)); 
  chmod $perm task_directory/file$i; 
  echo "Created file$i with perm $perm"; 
done; 
sum=0; 
for f in task_directory/*; do 
  p=$(stat -c '%a' "$f"); 
  sum=$((sum + p)); 
done; 
echo $sum"}

